    if not key or not pattern:
        return out

    # The key is a small colored pixel pattern. Its cells are enlarged into
    # square blocks to color the larger 8-shaped pattern.
    best = None
    for scale in range(1, 11):
        for flip in range(8):
            transformed = []
            for r, c, color in key:
                if flip & 4:
                    r, c = c, r
                if flip & 1:
                    r = -r
                if flip & 2:
                    c = -c
                transformed.append((r, c, color))
            rmin = min(r for r, c, v in transformed)
            cmin = min(c for r, c, v in transformed)
            transformed = [(r-rmin, c-cmin, v) for r, c, v in transformed]

            # Try every placement; measure how many pattern cells are covered.
            for top in range(h):
                for left in range(w):
                    mapping = {}
                    for r, c, color in transformed:
                        for dr in range(scale):
                            for dc in range(scale):
                                rr = top + r*scale + dr
                                cc = left + c*scale + dc
                                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 8:
                                    mapping[(rr, cc)] = color
                    score = len(mapping)
                    if best is None or score > best[0]:
                        best = (score, mapping)
    if best:
        for (r, c), color in best[1].items():
